-- =====================================================================
-- 原神角色股票数据（头像 URL + 角色名）—— 由 deploy/fetch-genshin-characters.mjs 生成
--
-- 数据来源：https://baike.mihoyo.com/ys/strategy/channel/map/37/39
-- 实际接口：https://act-api-takumi.mihoyo.com/common/blackboard/ys_obc/v1/home/content/list?app_sn=ys_obc&channel_id=25
-- 生成时间：2026/9/9 04:38:44
-- 角色数量：127 个（已按角色名去重）
--
-- 用法（DBeaver / Navicat）：连到 teyvat_stock 库，整个脚本一次性执行。
--
-- 特性：
--   * 可重复执行：靠 uk_stocks_code(code) / uk_stocks_name(name) 命中已有行
--   * 已存在的角色只更新 code + 头像，不改价格，避免打断 K 线与用户持仓
--   * 价格为按星级生成的固定基准价（五星 600~1400，四星 200~600）
--   * 总股本：五星 500 万 / 四星 800 万 / 其他 1000 万
-- =====================================================================

-- USE teyvat_stock;

START TRANSACTION;


ON DUPLICATE KEY UPDATE
  code       = VALUES(code),
  name       = VALUES(name),
  avatar_url = VALUES(avatar_url);

COMMIT;

-- 校验：应返回 127 行
SELECT COUNT(*) AS total, SUM(avatar_url LIKE '%mihoyo.com%') AS with_avatar FROM stocks;

SELECT id, code, name, LEFT(avatar_url, 78) AS avatar_url, price, total_shares
FROM stocks ORDER BY code LIMIT 10;
